23	@@ -0,0 +1,31 @@
24	+using Microsoft.Extensions.Options;
25	+using Relay.Core.Accounts;
26	+using Relay.Core.ActivityHealth;
27	+using Relay.Core.Calendar;
28	+using Relay.Core.Normality;
29	+
30	+namespace Relay.Api.Composition;
31	+
32	+public static class CoreServiceCollectionExtensions
33	+{
34	+    public static IServiceCollection AddRelayCore(this IServiceCollection services, IConfiguration configuration)
35	+    {
36	+        services.AddOptions<NormalityOptions>()
37	+            .Bind(configuration.GetSection(NormalityOptions.SectionName))
38	+            .ValidateDataAnnotations()
39	+            .Validate(
40	+                options => options.MinimumEligibleWeeks <= options.BaselineWeeks,
41	+                "Normality:MinimumEligibleWeeks must not exceed Normality:BaselineWeeks.")
42	+            .ValidateOnStart();
43	+        services.AddSingleton(serviceProvider => serviceProvider.GetRequiredService<IOptions<NormalityOptions>>().Value);
44	+
45	+        services.AddSingleton(TimeProvider.System);
46	+        services.AddSingleton<IWeekCalendar, WeekCalendar>();
47	+        services.AddSingleton<IWeeklyGridBuilder, WeeklyGridBuilder>();
48	+        services.AddSingleton<IBaselineEvaluator, BaselineEvaluator>();
49	+        services.AddSingleton<ILocationRanker, LocationRanker>();
50	+        services.AddScoped<IAccountService, AccountService>();
51	+        services.AddScoped<IActivityHealthService, ActivityHealthService>();
52	+        return services;
53	+    }
54	+}
